let database;
function open(){if(database)return database;database=new Promise((resolve,reject)=>{const req=indexedDB.open('mr-drews-four-corners',1);req.onupgradeneeded=()=>req.result.createObjectStore('games',{keyPath:'id'});req.onsuccess=()=>resolve(req.result);req.onerror=()=>{database=null;reject(req.error);};});return database;}
export async function saveProject(project){const db=await open();return new Promise((resolve,reject)=>{const tx=db.transaction('games','readwrite');tx.objectStore('games').put({id:project.id,name:project.name,updatedAt:Date.now(),project});tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||new Error('Could not save'));});}
export async function listProjects(){const db=await open();return new Promise((resolve,reject)=>{const req=db.transaction('games').objectStore('games').getAll();req.onsuccess=()=>resolve(req.result.sort((a,b)=>b.updatedAt-a.updatedAt));req.onerror=()=>reject(req.error);});}
export async function deleteProject(id){const db=await open();return new Promise((resolve,reject)=>{const tx=db.transaction('games','readwrite');tx.objectStore('games').delete(id);tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error);});}
export async function readFile(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(new Error('The file could not be read.'));r.readAsDataURL(file);});}
export async function mediaData(file){if(!/^(image|audio|video)\//.test(file.type))throw new Error('Choose an image, audio, or video file.');if(file.size>40*1024*1024)throw new Error('Choose a file smaller than 40 MB.');const src=await readFile(file);if(!file.type.startsWith('image/')||file.type==='image/gif'||file.type==='image/svg+xml')return src;return new Promise(resolve=>{const img=new Image();img.onerror=()=>resolve(src);img.onload=()=>{if(img.width<=1800&&img.height<=1800&&file.size<1.5*1024*1024){resolve(src);return;}const scale=Math.min(1,1800/Math.max(img.width,img.height));const canvas=document.createElement('canvas');canvas.width=Math.round(img.width*scale);canvas.height=Math.round(img.height*scale);canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);resolve(canvas.toDataURL('image/webp',.9));};img.src=src;});}
